assert all(len(values) == len(sources) == 16 for values in targets.values())
payload = {
    'review_method': 'Direct Codex AI technical review against all sixteen exact current English blocks. This is not native-speaker signoff. Technical identifiers, roles, defaults, counts, persistence semantics and palette-versus-token distinctions are retained.',
    'languages': {language: [{'label': source['label'], 'source': source['source'],
                              'context': source['context'], 'translation': target}
                             for source, target in zip(sources, values)]
                  for language, values in targets.items()},
}
(scratch / 'data-art-api-reviewed-targets-r1.json').write_text(json.dumps(payload, ensure_ascii=False, indent=2) + '\n')
print('Prepared sixteen source-bound API targets in all nine languages; private inputs only', flush=True)
